// Assay-screening ontology. Four classes (Compound, Target,
// AssayProtocol, AssayResult) plus their properties. Flat — no
// inheritance, no institutions; resources are connected via
// `core:resource`-typed properties with `class_types` constraints.

namespace core  = "urn:eigenius:core";
namespace assay = "urn:eigenius:demo:assay";

// --- Compound -------------------------------------------------------

class assay:Compound {
    description = "A small-molecule compound under screening.";
    requires assay:compound_id, assay:scaffold_class, assay:molecular_weight;
    recommends assay:logp;
}

property assay:compound_id : core:string {
    description = "Internal compound identifier (e.g., EIG_0042).";
}

property assay:scaffold_class : core:string {
    description = "Chemical scaffold family (pyrimidine, indazole, quinazoline, pyrazolopyrimidine).";
}

property assay:molecular_weight : core:float {
    description = "Molecular weight in g/mol.";
}

property assay:logp : core:float {
    description = "Calculated logP (lipophilicity).";
}

// --- Target ---------------------------------------------------------

class assay:Target {
    description = "A protein kinase target.";
    requires assay:target_name, assay:target_family;
}

property assay:target_name : core:string {
    description = "Target gene/protein symbol (e.g., CDK2).";
}

property assay:target_family : core:string {
    description = "Family the target belongs to (CDK, EGFR, Src, JAK, ...).";
}

// --- AssayProtocol --------------------------------------------------

class assay:AssayProtocol {
    description = "A kinase activity assay protocol.";
    requires assay:protocol_name, assay:incubation_minutes;
}

property assay:protocol_name : core:string {
    description = "Protocol name (Kinase-Glo, ADP-Glo, TR-FRET).";
}

property assay:incubation_minutes : core:integer {
    description = "Incubation duration in minutes.";
}

// --- AssayResult ----------------------------------------------------

class assay:AssayResult {
    description = "A single assay measurement: compound vs. target via a protocol, with IC50 and 95% confidence interval.";
    requires assay:compound, assay:target, assay:protocol,
             assay:ic50_nm, assay:replicate_count, assay:measurement_date, assay:passed_qc;
    recommends assay:ci_low_nm, assay:ci_high_nm;
}

property assay:compound : core:resource {
    description = "The compound being measured.";
    class_types assay:Compound;
}

property assay:target : core:resource {
    description = "The kinase target being measured.";
    class_types assay:Target;
}

property assay:protocol : core:resource {
    description = "The assay protocol used.";
    class_types assay:AssayProtocol;
}

property assay:ic50_nm : core:float {
    description = "Half-maximal inhibitory concentration in nM.";
}

property assay:ci_low_nm : core:float {
    description = "Lower bound of 95% confidence interval (nM).";
}

property assay:ci_high_nm : core:float {
    description = "Upper bound of 95% confidence interval (nM).";
}

property assay:replicate_count : core:integer {
    description = "Number of replicate measurements.";
}

property assay:measurement_date : core:string {
    description = "ISO 8601 date the measurement was taken.";
}

property assay:passed_qc : core:boolean {
    description = "Whether the result passed protocol-defined QC checks.";
}

