// Selectivity matrix — every QC-passing AssayResult, joined to its
// compound + target. This is the data a Phase 5 grouped-bar chart
// would consume (one bar per (compound, target) IC50; group by
// compound, colour by target).

USING "urn:eigenius:demo:assay:AssayResult"

MATCH AssayResult(?r) {
    "urn:eigenius:demo:assay:compound":         ?c,
    "urn:eigenius:demo:assay:target":           ?t,
    "urn:eigenius:demo:assay:ic50_nm":          ?ic50,
    "urn:eigenius:demo:assay:ci_low_nm":        ?ci_low,
    "urn:eigenius:demo:assay:ci_high_nm":       ?ci_high,
    "urn:eigenius:demo:assay:replicate_count":  ?n,
    "urn:eigenius:demo:assay:passed_qc":        ?qc
},
?c { "urn:eigenius:demo:assay:compound_id": ?compound_id },
?t { "urn:eigenius:demo:assay:target_name": ?target_name }
WHERE ?qc = true
RETURN [] {
    compound: ?compound_id,
    target:   ?target_name,
    ic50_nm:  ?ic50,
    ci_low:   ?ci_low,
    ci_high:  ?ci_high,
    n:        ?n
}
ORDER BY ?compound_id

// QC pass-rate by protocol. The chart Phase 5 would render: a donut
// or stacked bar chart showing how many results passed/failed per
// protocol — TR-FRET runs the very-weak EGFR off-target measurements
// and absorbs all the QC failures, while Kinase-Glo / ADP-Glo are
// clean.

USING "urn:eigenius:demo:assay:AssayResult"

MATCH AssayResult(?r) {
    "urn:eigenius:demo:assay:protocol":   ?p,
    "urn:eigenius:demo:assay:passed_qc":  ?qc
},
?p { "urn:eigenius:demo:assay:protocol_name": ?protocol_name }
RETURN [] {
    protocol: ?protocol_name,
    qc:       ?qc
}
ORDER BY ?protocol_name

// IC50 selectivity profile — grouped bar chart. One group per
// compound; one bar per target within each group; bar height is
// IC50 in nM (lower = more potent). The CDK-selective compounds
// (EIG_0042, EIG_0117, EIG_0291, etc.) show short bars on their
// preferred target and tall bars on EGFR; the EGFR-selective
// EIG_0203 shows the inverse.
//
// `nb.rows(document)` decodes the ResultSet CBOR into plain objects
// keyed by short_name; the cell then pivots into the
// GroupedVerticalBarChartData shape.

const resp = await eigen.query(`
USING "urn:eigenius:demo:assay:AssayResult"
MATCH AssayResult(?r) {
    "urn:eigenius:demo:assay:compound":         ?c,
    "urn:eigenius:demo:assay:target":           ?t,
    "urn:eigenius:demo:assay:ic50_nm":          ?ic50,
    "urn:eigenius:demo:assay:passed_qc":        ?qc
},
?c { "urn:eigenius:demo:assay:compound_id": ?compound_id },
?t { "urn:eigenius:demo:assay:target_name": ?target_name }
WHERE ?qc = true
RETURN [] {
    compound: ?compound_id,
    target:   ?target_name,
    ic50_nm:  ?ic50
}
`);

const rows = nb.rows(resp.document);

// Pivot rows → groups keyed by compound, with a series entry per target.
const targetColors = {
  CDK2: "#5b88c5",
  CDK4: "#37a172",
  CDK6: "#a45fa1",
  EGFR: "#cf6f1e",
};
const byCompound = new Map();
for (const row of rows) {
  const c = String(row.compound);
  if (!byCompound.has(c)) byCompound.set(c, []);
  byCompound.get(c).push({
    key: String(row.target),
    legend: String(row.target),
    data: Number(row.ic50_nm),
    color: targetColors[String(row.target)],
  });
}
const data = Array.from(byCompound.entries())
  .sort(([a], [b]) => a.localeCompare(b))
  .map(([name, series]) => ({ name, series }));

console.log(`charting ${rows.length} measurements across ${data.length} compounds`);

return h(charts.GroupedVerticalBarChart, {
  data,
  height: 320,
  width: 800,
  yAxisTitle: "IC₅₀ (nM)",
  xAxisTitle: "Compound",
  chartTitle: "IC₅₀ selectivity profile",
});

// QC pass / fail breakdown across all 24 results. Donut showing how
// the QC failures concentrate on the very-weak EGFR off-target
// measurements (which run on the TR-FRET protocol — the next chart
// would slice further by protocol).

const resp = await eigen.query(`
USING "urn:eigenius:demo:assay:AssayResult"
MATCH AssayResult(?r) {
    "urn:eigenius:demo:assay:passed_qc": ?qc
}
RETURN [] {
    qc: ?qc
}
`);

const rows = nb.rows(resp.document);
const pass = rows.filter((r) => r.qc === true).length;
const fail = rows.length - pass;

return h(charts.DonutChart, {
  data: {
    chartTitle: "QC pass rate",
    chartData: [
      { legend: "Passed", data: pass, color: "#37a172" },
      { legend: "Failed", data: fail, color: "#cf6f1e" },
    ],
  },
  innerRadius: 55,
  height: 220,
  width: 220,
  valueInsideDonut: pass + fail,
});
